void stencil3d(TYPE C[2], TYPE orig[SIZE], TYPE sol[SIZE]) {
    // initialize sol with original values for boundaries
    for (int idx = 0; idx != SIZE; idx++) {
        sol[idx] = orig[idx];
    }

